-- MEVRA 2.0. Additive only: no existing column, row or constraint value is removed. Reverse with db/migrations/down/004_v2.sql.
-- Catalogue ---------------------------------------------------------------------
ALTER TABLE categories ADD COLUMN vertical text NOT NULL DEFAULT 'dry_fruits' CHECK (vertical IN ('dry_fruits','snack_king','pantry','gifting','business')),
  ADD COLUMN parent_id uuid REFERENCES categories(id), ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN seo_title text, ADD COLUMN seo_desc text;
CREATE INDEX ON categories (vertical, sort);
ALTER TABLE products ADD COLUMN status text NOT NULL DEFAULT 'launch' CHECK (status IN ('launch','seasonal','gift_only','prelaunch','draft','out_of_stock','discontinued')),
  ADD COLUMN vertical text NOT NULL DEFAULT 'dry_fruits' CHECK (vertical IN ('dry_fruits','snack_king','pantry','gifting','business')),
  ADD COLUMN variety text, ADD COLUMN hindi text, ADD COLUMN processing text, ADD COLUMN allergens text, ADD COLUMN shelf_life text,
  ADD COLUMN nutrition jsonb, ADD COLUMN nutrition_verified boolean NOT NULL DEFAULT false, ADD COLUMN certifications jsonb NOT NULL DEFAULT '[]', ADD COLUMN legal jsonb NOT NULL DEFAULT '{}',
  ADD COLUMN sweetened text CHECK (sweetened IN ('sweetened','unsweetened','not_applicable')), ADD COLUMN season_months int[] NOT NULL DEFAULT '{}',
  ADD COLUMN model_key text, ADD COLUMN pack_type text NOT NULL DEFAULT 'pouch', ADD COLUMN video_url text, ADD COLUMN seo_title text, ADD COLUMN seo_desc text, ADD COLUMN story text NOT NULL DEFAULT '',
  ADD COLUMN taste_tags text[] NOT NULL DEFAULT '{}', ADD COLUMN occasions text[] NOT NULL DEFAULT '{}',
  ADD COLUMN subscription_ok boolean NOT NULL DEFAULT false, ADD COLUMN loyalty_ok boolean NOT NULL DEFAULT true, ADD COLUMN promo_ok boolean NOT NULL DEFAULT true, ADD COLUMN mix_ok boolean NOT NULL DEFAULT false, ADD COLUMN gift_ok boolean NOT NULL DEFAULT false, ADD COLUMN gift_surcharge_paise int NOT NULL DEFAULT 0,
  ADD COLUMN approval text NOT NULL DEFAULT 'approved' CHECK (approval IN ('draft','in_review','approved')), ADD COLUMN data_note text;
ALTER TABLE products DROP CONSTRAINT products_kind_check, ADD CONSTRAINT products_kind_check CHECK (kind IN ('single','bundle','custom'));
CREATE INDEX ON products (vertical, status); CREATE INDEX ON products (variety);
ALTER TABLE product_variants ADD COLUMN price_basis text NOT NULL DEFAULT 'planning' CHECK (price_basis IN ('planning','derived','demo','confirmed')), ADD COLUMN ship_alloc_paise int CHECK (ship_alloc_paise >= 0), ADD COLUMN discount_ceiling_bp int CHECK (discount_ceiling_bp BETWEEN 0 AND 5000);
CREATE TABLE product_relations (product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, related_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('pair','alternative','upgrade')), sort int NOT NULL DEFAULT 0, PRIMARY KEY (product_id, related_id, kind), CHECK (product_id <> related_id));
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('image','model3d','video','vector')), folder text NOT NULL, path text NOT NULL UNIQUE, alt text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'illustrative' CHECK (status IN ('supplied','illustrative','photography','retired')), bytes int, created_at timestamptz NOT NULL DEFAULT now());
/* One rule for "can this be bought now", used by listing, cart and checkout alike. */
CREATE VIEW variant_state AS
SELECT v.id AS variant_id, p.id AS product_id,
  CASE WHEN p.kind = 'bundle' THEN (SELECT min(CASE WHEN ci.tracked THEN GREATEST(0,(ci.on_hand-ci.reserved)/bc.qty) END) FROM bundle_components bc JOIN inventory ci ON ci.variant_id=bc.component_variant_id WHERE bc.bundle_variant_id=v.id) WHEN i.tracked THEN GREATEST(0,i.on_hand-i.reserved) END AS avail,
  (p.active AND v.active AND p.approval='approved' AND p.kind <> 'custom' AND v.price_paise IS NOT NULL AND v.price_basis <> 'demo'
    AND (p.status='launch' OR (p.status='seasonal' AND (cardinality(p.season_months)=0 OR extract(month FROM now())::int = ANY(p.season_months))))
    AND (p.kind <> 'bundle' OR NOT EXISTS (SELECT 1 FROM bundle_components bc JOIN product_variants cv ON cv.id=bc.component_variant_id JOIN products cp ON cp.id=cv.product_id WHERE bc.bundle_variant_id=v.id AND (NOT cp.active OR cp.status NOT IN ('launch','seasonal','gift_only') OR cv.price_paise IS NULL)))) AS on_sale,
  CASE WHEN NOT p.active OR NOT v.active OR p.status='discontinued' THEN 'No longer available' WHEN p.status='draft' OR p.approval<>'approved' THEN 'Not published' WHEN p.status='prelaunch' THEN 'Coming soon' WHEN p.status='gift_only' THEN 'Available in gift boxes' WHEN p.status='out_of_stock' THEN 'Out of stock'
    WHEN p.status='seasonal' AND cardinality(p.season_months)>0 AND NOT extract(month FROM now())::int = ANY(p.season_months) THEN 'Out of season' WHEN v.price_paise IS NULL THEN 'Price to be announced' WHEN v.price_basis='demo' THEN 'Price being confirmed' END AS reason
FROM product_variants v JOIN products p ON p.id=v.product_id LEFT JOIN inventory i ON i.variant_id=v.id;

-- Custom mixes, gift boxes --------------------------------------------------------
CREATE TABLE custom_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('mix','gift')), title text NOT NULL, config jsonb NOT NULL, price_paise int NOT NULL CHECK (price_paise > 0), list_paise int NOT NULL, weight_g int NOT NULL CHECK (weight_g > 0), gift_message text, gift_token text UNIQUE, customer_id uuid REFERENCES customers(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK (list_paise >= price_paise));
ALTER TABLE cart_items ADD COLUMN id uuid NOT NULL DEFAULT gen_random_uuid(), ADD COLUMN custom_id uuid REFERENCES custom_items(id);
ALTER TABLE cart_items DROP CONSTRAINT cart_items_pkey, ADD PRIMARY KEY (id);
CREATE UNIQUE INDEX cart_items_std ON cart_items (cart_id, variant_id) WHERE custom_id IS NULL; CREATE UNIQUE INDEX cart_items_custom ON cart_items (cart_id, custom_id) WHERE custom_id IS NOT NULL;
ALTER TABLE order_items ADD COLUMN custom_id uuid REFERENCES custom_items(id), ADD COLUMN custom jsonb;
ALTER TABLE carts ADD COLUMN use_points int NOT NULL DEFAULT 0 CHECK (use_points >= 0), ADD COLUMN reward_id uuid, ADD COLUMN delivery_date date;
ALTER TABLE orders ADD COLUMN points_used int NOT NULL DEFAULT 0, ADD COLUMN points_discount_paise int NOT NULL DEFAULT 0, ADD COLUMN requested_date date, ADD COLUMN reward jsonb;
ALTER TABLE gift_tiers ADD COLUMN compartments int NOT NULL DEFAULT 4, ADD COLUMN portion_g int NOT NULL DEFAULT 100;
CREATE TABLE gift_sleeves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, bg text NOT NULL, fg text NOT NULL, accent text NOT NULL, price_paise int NOT NULL DEFAULT 0 CHECK (price_paise >= 0), tiers text[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, sort int NOT NULL DEFAULT 0);
CREATE TABLE mix_bases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, blurb text NOT NULL, recipe jsonb NOT NULL, active boolean NOT NULL DEFAULT true, sort int NOT NULL DEFAULT 0);

-- Loyalty -------------------------------------------------------------------------
ALTER TABLE customers ADD COLUMN birthday date, ADD COLUMN taste jsonb, ADD COLUMN prefs jsonb NOT NULL DEFAULT '{}';
CREATE TABLE loyalty_tiers (slug text PRIMARY KEY, name text NOT NULL, threshold_paise int NOT NULL DEFAULT 0 CHECK (threshold_paise >= 0), multiplier_bp int NOT NULL DEFAULT 10000, benefits text[] NOT NULL DEFAULT '{}', sort int NOT NULL);
CREATE TABLE loyalty_accounts (customer_id uuid PRIMARY KEY REFERENCES customers(id), tier text NOT NULL DEFAULT 'member' REFERENCES loyalty_tiers(slug) DEFERRABLE INITIALLY DEFERRED, referral_code text NOT NULL UNIQUE, flagged boolean NOT NULL DEFAULT false, flag_note text, joined_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE loyalty_ledger (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, customer_id uuid NOT NULL REFERENCES loyalty_accounts(customer_id), type text NOT NULL CHECK (type IN ('earned','redeemed','reversed','expired','adjusted','bonus')), points int NOT NULL CHECK (points <> 0), status text NOT NULL DEFAULT 'posted' CHECK (status IN ('pending','posted','void')), source text NOT NULL, order_id uuid REFERENCES orders(id), ref_key text NOT NULL UNIQUE, expires_at timestamptz, note text, actor text NOT NULL DEFAULT 'system', at timestamptz NOT NULL DEFAULT now(), CHECK ((type IN ('earned','bonus') AND points > 0) OR (type IN ('redeemed','expired') AND points < 0) OR type IN ('reversed','adjusted')));
CREATE INDEX ON loyalty_ledger (customer_id, at DESC); CREATE INDEX ON loyalty_ledger (order_id);
CREATE VIEW loyalty_balances AS SELECT a.customer_id, COALESCE(sum(l.points) FILTER (WHERE l.status='posted'),0)::int AS balance, COALESCE(sum(l.points) FILTER (WHERE l.status='pending'),0)::int AS pending, COALESCE(sum(l.points) FILTER (WHERE l.status='posted' AND l.type IN ('earned','bonus')),0)::int AS lifetime FROM loyalty_accounts a LEFT JOIN loyalty_ledger l ON l.customer_id=a.customer_id GROUP BY 1;
CREATE TABLE rewards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', kind text NOT NULL CHECK (kind IN ('voucher','sample','product','bundle','benefit')), points int NOT NULL CHECK (points > 0), value_paise int, variant_id uuid REFERENCES product_variants(id), min_tier text REFERENCES loyalty_tiers(slug), stock int, active boolean NOT NULL DEFAULT true, sort int NOT NULL DEFAULT 0);
CREATE TABLE reward_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reward_id uuid NOT NULL REFERENCES rewards(id), customer_id uuid NOT NULL REFERENCES customers(id), points int NOT NULL, status text NOT NULL DEFAULT 'claimed' CHECK (status IN ('claimed','attached','fulfilled','cancelled')), order_id uuid REFERENCES orders(id), coupon_code text, at timestamptz NOT NULL DEFAULT now());
ALTER TABLE carts ADD CONSTRAINT carts_reward_fk FOREIGN KEY (reward_id) REFERENCES reward_claims(id);
ALTER TABLE coupons ADD COLUMN customer_id uuid REFERENCES customers(id);
CREATE TABLE referrals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), referrer_id uuid NOT NULL REFERENCES customers(id), referee_id uuid NOT NULL UNIQUE REFERENCES customers(id), code text NOT NULL, status text NOT NULL DEFAULT 'joined' CHECK (status IN ('joined','qualified','rewarded','flagged','rejected')), reason text, order_id uuid REFERENCES orders(id), at timestamptz NOT NULL DEFAULT now(), CHECK (referrer_id <> referee_id));
CREATE INDEX ON referrals (referrer_id);
-- Gamification ----------------------------------------------------------------------
CREATE TABLE challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, description text NOT NULL, rule jsonb NOT NULL, points int NOT NULL DEFAULT 0 CHECK (points >= 0), badge text, kind text NOT NULL DEFAULT 'weekly' CHECK (kind IN ('weekly','standing','stamp','badge')), rotation int, active boolean NOT NULL DEFAULT true, sort int NOT NULL DEFAULT 0);
CREATE TABLE challenge_progress (customer_id uuid NOT NULL REFERENCES customers(id), challenge_id uuid NOT NULL REFERENCES challenges(id), period text NOT NULL DEFAULT 'once', progress int NOT NULL DEFAULT 0, completed_at timestamptz, PRIMARY KEY (customer_id, challenge_id, period));
-- Refill, collections, notices ----------------------------------------------------------
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ref text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES customers(id), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','cancelled')), interval_days int NOT NULL CHECK (interval_days BETWEEN 7 AND 180), next_date date NOT NULL, address_id uuid REFERENCES addresses(id) ON DELETE SET NULL, mode text NOT NULL DEFAULT 'simulation' CHECK (mode IN ('simulation','live')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscription_items (subscription_id uuid NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES product_variants(id), qty int NOT NULL CHECK (qty BETWEEN 1 AND 20), PRIMARY KEY (subscription_id, variant_id));
CREATE TABLE subscription_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, subscription_id uuid NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE, kind text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saved_collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), name text NOT NULL, kind text NOT NULL DEFAULT 'collection' CHECK (kind IN ('collection','pantry')), shared_token text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (customer_id, name));
CREATE TABLE saved_items (collection_id uuid NOT NULL REFERENCES saved_collections(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, PRIMARY KEY (collection_id, product_id));
CREATE TABLE notices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), kind text NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', href text, read_at timestamptz, at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON notices (customer_id, at DESC);
-- B2B -------------------------------------------------------------------------------
CREATE TABLE b2b_accounts (customer_id uuid PRIMARY KEY REFERENCES customers(id), business text NOT NULL, business_type text NOT NULL, gstin text, city text NOT NULL, pin text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','suspended')), credit_limit_paise int NOT NULL DEFAULT 0 CHECK (credit_limit_paise >= 0), terms_days int NOT NULL DEFAULT 0 CHECK (terms_days BETWEEN 0 AND 60), notes text, approved_by text, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE b2b_prices ADD COLUMN product_id uuid REFERENCES products(id), ADD COLUMN pack_kg numeric(8,2) CHECK (pack_kg > 0), ADD COLUMN moq_packs int NOT NULL DEFAULT 1 CHECK (moq_packs > 0), ADD COLUMN spec text NOT NULL DEFAULT '', ADD COLUMN segment text NOT NULL DEFAULT 'Kitchen', ADD COLUMN status text NOT NULL DEFAULT 'launch' CHECK (status IN ('launch','prelaunch','draft')), ADD COLUMN price_basis text NOT NULL DEFAULT 'planning';
CREATE TABLE b2b_account_prices (customer_id uuid NOT NULL REFERENCES b2b_accounts(customer_id), item_id uuid NOT NULL REFERENCES b2b_prices(id), price_paise_per_kg int NOT NULL CHECK (price_paise_per_kg > 0), PRIMARY KEY (customer_id, item_id));
CREATE TABLE b2b_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ref text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES b2b_accounts(customer_id), kind text NOT NULL DEFAULT 'quote' CHECK (kind IN ('quote','sample')), status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','quoted','accepted','declined','fulfilled','cancelled')), note text, admin_note text, valid_until date, delivery_paise int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE b2b_quote_items (quote_id uuid NOT NULL REFERENCES b2b_quotes(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES b2b_prices(id), packs int NOT NULL CHECK (packs > 0), pack_kg numeric(8,2) NOT NULL, price_paise_per_kg int, PRIMARY KEY (quote_id, item_id));
-- Content & community ---------------------------------------------------------------
CREATE TABLE articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, kind text NOT NULL CHECK (kind IN ('journal','academy','landing','occasion')), topic text NOT NULL DEFAULT '', title text NOT NULL, dek text NOT NULL DEFAULT '', body jsonb NOT NULL DEFAULT '[]', cover text, product_slugs text[] NOT NULL DEFAULT '{}', quiz jsonb, filter jsonb, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')), seo_title text, seo_desc text, minutes int NOT NULL DEFAULT 4, sort int NOT NULL DEFAULT 0, published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recipes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, dek text NOT NULL DEFAULT '', cover text, prep_min int NOT NULL, cook_min int NOT NULL DEFAULT 0, serves int NOT NULL, ingredients jsonb NOT NULL, steps jsonb NOT NULL, tags text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')), author text NOT NULL DEFAULT 'MEVRA kitchen', sort int NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saved_recipes (customer_id uuid NOT NULL REFERENCES customers(id), recipe_id uuid NOT NULL REFERENCES recipes(id) ON DELETE CASCADE, PRIMARY KEY (customer_id, recipe_id));
CREATE TABLE submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('recipe','photo','story')), customer_id uuid NOT NULL REFERENCES customers(id), product_id uuid REFERENCES products(id), display_name text NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', file text, consent boolean NOT NULL CHECK (consent), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quiz_results (customer_id uuid NOT NULL REFERENCES customers(id), slug text NOT NULL, score int NOT NULL, total int NOT NULL, at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (customer_id, slug));
CREATE TABLE banners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), placement text NOT NULL CHECK (placement IN ('home','shop','snack_king','pantry','gifting')), title text NOT NULL, copy text NOT NULL DEFAULT '', href text NOT NULL, image text, starts_on date, ends_on date, active boolean NOT NULL DEFAULT true, sort int NOT NULL DEFAULT 0);
-- Growth -----------------------------------------------------------------------------
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, source text NOT NULL, medium text NOT NULL, campaign text NOT NULL, landing text NOT NULL DEFAULT '/', budget_paise int, bonus_bp int NOT NULL DEFAULT 0 CHECK (bonus_bp BETWEEN 0 AND 30000), starts_on date, ends_on date, status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','active','ended')), notes text, UNIQUE (source, medium, campaign));
CREATE TABLE experiments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, name text NOT NULL, hypothesis text NOT NULL DEFAULT '', variants jsonb NOT NULL, goal text NOT NULL DEFAULT 'order_placed', status text NOT NULL DEFAULT 'off' CHECK (status IN ('off','running','ended')), started_at timestamptz, ended_at timestamptz);
CREATE TABLE integration_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, adapter text NOT NULL, action text NOT NULL, outcome text NOT NULL CHECK (outcome IN ('recorded','sent','failed','skipped')), detail jsonb NOT NULL DEFAULT '{}', at timestamptz NOT NULL DEFAULT now());
-- Quality & operations --------------------------------------------------------------
ALTER TABLE stock_movements DROP CONSTRAINT stock_movements_kind_check, ADD CONSTRAINT stock_movements_kind_check CHECK (kind IN ('receive','adjust','reserve','release','ship','return','damage'));
CREATE TABLE quality_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lot_id uuid NOT NULL REFERENCES lots(id) ON DELETE CASCADE, check_name text NOT NULL, result text NOT NULL, ok boolean, inspector text NOT NULL, at timestamptz NOT NULL DEFAULT now());
ALTER TABLE reviews ADD COLUMN photo text;
ALTER TABLE enquiries DROP CONSTRAINT enquiries_kind_check, ADD CONSTRAINT enquiries_kind_check CHECK (kind IN ('gifting_corporate','gifting_wedding','gifting_festival','gifting_personal','b2b','contact'));
ALTER TABLE enquiries ADD COLUMN quote jsonb;
-- Custom items and demand: custom lines have no component stock
DROP VIEW IF EXISTS demand_facts;
CREATE VIEW demand_facts AS
SELECT o.placed_at, o.status, o.id AS order_id, CASE WHEN c.value IS NULL THEN i.variant_id ELSE (c.value->>'variant_id')::uuid END AS variant_id, i.qty * COALESCE((c.value->>'qty')::int, 1) AS units
FROM order_items i JOIN orders o ON o.id = i.order_id LEFT JOIN LATERAL jsonb_array_elements(i.components) c(value) ON true;
